  if(live) video.classList.remove('is-pending');
  else {
    var pb = R.querySelector('[data-video-play]');
    if(pb){ pb.setAttribute('aria-disabled', 'true'); pb.setAttribute('aria-label', 'Video publishing soon'); }
  }
