    if(!e.target.closest('[data-video-play]')) return;
    if(!live){ toast('The guide is publishing soon. Questions? Call (832) 979-6758.'); return; }
    var f = document.createElement('iframe');
    f.title = 'Pump Room Specifications Guide';
